{
  "groups": [
    {
      "group_id": "ultra_low_fixed_rate_2021_lock_in",
      "rule": "rate_type == 'fixed' and origination_year == 2021 and mortgage_rate_pct <= 3.0",
      "rationale": "Borrowers holding ultra-low fixed rates from the pandemic trough face severe payment shock if renewing at current market rates, making them price-sensitive negotiators."
    },
    {
      "group_id": "high_rate_variable_rate_squeezed",
      "rule": "rate_type == 'variable' and mortgage_rate_pct > 5.0",
      "rationale": "Variable-rate borrowers who experienced rapid rate hikes face elevated monthly debt burdens and are highly likely to shop around for lower fixed options."
    },
    {
      "group_id": "affluent_wealth_management_investors",
      "rule": "household_income_cad >= 137184 and has_investments == True and credit_score_band == '720_plus'",
      "rationale": "High-income, high-credit investors with established wealth relationships value advisory support over modest rate discounts and are strong targets for cross-sell retention."
    },
    {
      "group_id": "budget_constrained_families_with_children",
      "rule": "household_income_cad < 75000 and n_children >= 2 and mortgage_payment_monthly_cad > 2000",
      "rationale": "Lower-income households managing multiple children and significant monthly mortgage payments prioritize immediate cash flow relief and payment stability."
    },
    {
      "group_id": "digital_native_uninsured_refinancers",
      "rule": "channel == 'digital' and insured_flag == False and has_advisor == False",
      "rationale": "Self-directed borrowers without dedicated advisors who rely on digital channels are agile comparison shoppers prone to switching for competitive online rates."
    },
    {
      "group_id": "tenured_branch_loyals",
      "rule": "td_tenure_months >= 90 and channel == 'branch' and has_advisor == True",
      "rationale": "Long-standing relationship clients who engage through physical branches and advisors exhibit high institutional loyalty and lower churn propensity."
    },
    {
      "group_id": "recent_life_event_budget_disrupted",
      "rule": "life_event_6m == True and td_deposits_3m_change_cad < 0",
      "rationale": "Borrowers experiencing major household changes paired with declining liquid reserves may require restructured terms or proactive outreach to prevent delinquency or emergency lender switching."
    }
  ]
}
